    "pda_practical_counterfactual": "Someone in charge should have set up a spotter system"
  },
  {
    "ae_shared_affect": "feel that same jolt of panic",
    "ce_understood_harm": "five people die under the wheels",
    "pda_practical_counterfactual": "company should have installed automatic track sensors"
  },
  {
    "ae_shared_affect": "tightens right along with them, like their scare",
    "ce_understood_harm": "that train ploughs into all five of them",
    "pda_practical_counterfactual": "Somebody should have scheduled a lookout"
  },
  {
    "ae_shared_affect": "feel just as rattled as they look",
    "ce_understood_harm": "the train hits them dead on",
    "pda_practical_counterfactual": "crews had radios linked to signal control"
  },
  {
    "ae_shared_affect": "something like their fear settles into me too",
    "ce_understood_harm": "train reaches all five and there's no walking that back",
    "pda_practical_counterfactual": "dispatch should have held this train"
  },
  {
    "ae_shared_affect": "throat go tight, mirroring whatever's gripping them",
    "ce_understood_harm": "the train crashes into all five",
    "pda_practical_counterfactual": "proper barrier gate at the entrance to this section"
  },
  {
    "ae_shared_affect": "dread is running through them seems to run through me",
    "ce_understood_harm": "train reaches them, and that's five lives ended",
    "pda_practical_counterfactual": "someone had synced the maintenance schedule"
  },
  {
    "ae_shared_affect": "stirs up the same unease in me",
    "ce_understood_harm": "it strikes all five workers",
    "pda_practical_counterfactual": "radio check before releasing an unmanned train"
  },
  {
    "ae_shared_affect": "jab of the same alarm gripping them",
    "ce_understood_harm": "the train hits all five",
    "pda_practical_counterfactual": "supervisor should have posted a flagman"
  },
  {
    "ae_shared_affect": "same tight, urgent fear that seems to be driving them",
    "ce_understood_harm": "it kills all five",
    "pda_practical_counterfactual": "track control should have blocked this line"
  }
]
